window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-dc03aa663d5769c2"]={"versions": [{"id": "FIG-dc03aa663d5769c2", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-ECU-Konfigurations-Metamodell (UML-Klassendiagramm) zur Spezifikation der Fehlerereignis-Referenzen des BSW-Moduls <code>UdpNm</code> (UDP Network Management) an den Diagnostic Event Manager (<code>Dem</code>). Es definiert die Konfigurationsstruktur auf Module- und Container-Ebene (<code>EcucModuleDef</code>, <code>EcucParamConfContainerDef</code>, <code>EcucSymbolicNameReferenceDef</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>UdpNm : EcucModuleDef</code>: Wurzelmoduldefinition mit Multiplizität <code>0..1</code>.\n</li><li><code>UdpNmGlobalConfig : EcucParamConfContainerDef</code>: Globaler Konfigurationscontainer, über die Kompositionsrolle <code>+container</code> im Modul eingebettet. Enthält das Attribut <code>multipleConfigurationContainer = true</code>.\n</li><li><code>UdpNmDemEventParameterRefs : EcucParamConfContainerDef</code>: Sub-Container von <code>UdpNmGlobalConfig</code> (Rolle <code>+subContainer</code>), Multiplizität <code>0..1</code> (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>).\n</li><li><code>UDPNM_E_TCPIP_TRANSMIT_ERROR : EcucSymbolicNameReferenceDef</code>: Symbolische Referenzdefinition (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>), über <code>+reference</code> im Container <code>UdpNmDemEventParameterRefs</code> enthalten, zeigt über <code>+destination</code> auf das Ziel <code>DemEventParameter</code>.\n</li><li><code>UDPNM_E_NETWORK_TIMEOUT : EcucSymbolicNameReferenceDef</code>: Symbolische Referenzdefinition (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>), über <code>+reference</code> im Container <code>UdpNmDemEventParameterRefs</code> enthalten, zeigt über <code>+destination</code> auf das Ziel <code>DemEventParameter</code>.\n</li><li><code>DemEventParameter : EcucParamConfContainerDef</code>: Externer Zielcontainer (aus dem Dem-Metamodell, <code>(from Dem)</code>), Multiplizität <code>1..65535</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statische Konfigurations-Metamodell-Definition liegt kein zeitlicher Ablauf vor. Zur Konfigurations- und Generierungszeit referenziert das Modul <code>UdpNm</code> über die symbolischen Referenzen <code>UDPNM_E_TCPIP_TRANSMIT_ERROR</code> und <code>UDPNM_E_NETWORK_TIMEOUT</code> konkrete Fehlerereignisse des Dem, an die zur Laufzeit Übertragungsfehler des TCP/IP-Stacks sowie Netzwerk-Timeouts via <code>Dem_SetEventStatus</code> gemeldet werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Spezifikation ist normativ verbindlich für ECU-Konfigurationswerkzeuge (BSW-Generatoren) des UDP Network Management. Der Container <code>UdpNmGlobalConfig</code> ist als <code>multipleConfigurationContainer = true</code> deklariert, was die Unterstützung mehrerer Konfigurationssätze innerhalb der Modulkonfiguration festlegt. Beide Dem-Ereignisreferenzen sind optional (<code>0..1</code>), verweisen bei Konfiguration jedoch zwingend auf eine gültige <code>DemEventParameter</code>-Instanz.</p>"}, {"id": "FIG-e4ab115f0a171c86", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-ECU-Konfigurations-Metamodell (UML-Klassendiagramm) zur Spezifikation der Fehlerereignis-Referenzen des BSW-Moduls <code>UdpNm</code> (UDP Network Management) an den Diagnostic Event Manager (<code>Dem</code>). Es definiert die Konfigurationsstruktur auf Module- und Container-Ebene (<code>EcucModuleDef</code>, <code>EcucParamConfContainerDef</code>, <code>EcucSymbolicNameReferenceDef</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>UdpNm : EcucModuleDef</code>: Wurzelmoduldefinition mit Multiplizität <code>0..1</code>.\n</li><li><code>UdpNmGlobalConfig : EcucParamConfContainerDef</code>: Globaler Konfigurationscontainer, über die Kompositionsrolle <code>+container</code> im Modul eingebettet.\n</li><li><code>UdpNmDemEventParameterRefs : EcucParamConfContainerDef</code>: Sub-Container von <code>UdpNmGlobalConfig</code> (Rolle <code>+subContainer</code>), Multiplizität <code>0..1</code> (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>).\n</li><li><code>UDPNM_E_TCPIP_TRANSMIT_ERROR : EcucSymbolicNameReferenceDef</code>: Symbolische Referenzdefinition (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>), über <code>+reference</code> im Container <code>UdpNmDemEventParameterRefs</code> enthalten, zeigt über <code>+destination</code> auf das Ziel <code>DemEventParameter</code>.\n</li><li><code>UDPNM_E_NETWORK_TIMEOUT : EcucSymbolicNameReferenceDef</code>: Symbolische Referenzdefinition (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>), über <code>+reference</code> im Container <code>UdpNmDemEventParameterRefs</code> enthalten, zeigt über <code>+destination</code> auf das Ziel <code>DemEventParameter</code>.\n</li><li><code>DemEventParameter : EcucParamConfContainerDef</code>: Externer Zielcontainer (aus dem Dem-Metamodell, <code>(from Dem)</code>), Multiplizität <code>1..65535</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statische Konfigurations-Metamodell-Definition liegt kein zeitlicher Ablauf vor. Zur Konfigurations- und Generierungszeit referenziert das Modul <code>UdpNm</code> über die symbolischen Referenzen <code>UDPNM_E_TCPIP_TRANSMIT_ERROR</code> und <code>UDPNM_E_NETWORK_TIMEOUT</code> konkrete Fehlerereignisse des Dem, an die zur Laufzeit Übertragungsfehler des TCP/IP-Stacks sowie Netzwerk-Timeouts via <code>Dem_SetEventStatus</code> gemeldet werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Spezifikation ist normativ verbindlich für ECU-Konfigurationswerkzeuge (BSW-Generatoren) des UDP Network Management. Beide Dem-Ereignisreferenzen innerhalb von <code>UdpNmDemEventParameterRefs</code> sind optional (<code>0..1</code>), verweisen bei Konfiguration jedoch zwingend auf eine gültige <code>DemEventParameter</code>-Instanz.</p>"}], "trans": [{"from": "FIG-dc03aa663d5769c2", "to": "FIG-e4ab115f0a171c86", "fr": "R4.1.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>UdpNmGlobalConfig</code>: Das Attribut <code>multipleConfigurationContainer = true</code> wurde entfernt.\n</li></ul>"}]};
